<section class="card"><div class="card-header"><h2>Cada comentario, una oportunidad de mejorar</h2><p>Las correcciones se atienden al registrar una nueva versión.</p></div><form method="get" class="toolbar"><input type="hidden" name="page" value="observations"><label class="sr-only" for="obs-q">Buscar observaciones</label><input id="obs-q" name="q" value="<?= e($q) ?>" placeholder="Cliente o comentario"><label class="sr-only" for="obs-status">Estado</label><select id="obs-status" name="status"><option value="">Todas</option><option value="pending" <?= $status === 'pending' ? 'selected' : '' ?>>Pendientes</option><option value="resolved" <?= $status === 'resolved' ? 'selected' : '' ?>>Atendidas</option></select><button class="btn btn-primary">Filtrar</button></form><div class="section-body"><?php $found = false; foreach ($allObservations as $observation): if (($q !== '' && mb_stripos($observation['client'] . ' ' . $observation['comment'], $q) === false) || ($status === 'pending' && $observation['resolved']) || ($status === 'resolved' && !$observation['resolved'])) continue; $found = true; ?><article class="observation"><div class="between"><a href="index.php?page=detail&amp;id=<?= e($observation['contract_id']) ?>"><strong><?= e($observation['client']) ?></strong> · <?= e($observation['code']) ?></a><span class="badge <?= $observation['resolved'] ? 'approved' : 'observed' ?>"><?= $observation['resolved'] ? 'Atendida' : 'Pendiente' ?></span></div><h3><?= e($observation['category']) ?></h3><p><?= nl2br(e($observation['comment'])) ?></p><small><?= e($observation['user_name']) ?> · V<?= (int) $observation['version_number'] ?> · <?= e(date('d/m/Y H:i', strtotime($observation['created_at']))) ?></small></article><?php endforeach ?><?php if (!$found): ?><p class="empty-state">No encontramos observaciones para estos filtros.</p><?php endif ?></div></section>

